#ifndef MESH_CUBED_SPHERE_ANCHORED_RADIAL_SCRI_PROBE_HPP_
#define MESH_CUBED_SPHERE_ANCHORED_RADIAL_SCRI_PROBE_HPP_
#include "mesh/cubed_sphere/radial_scri_jet_probe.hpp"
namespace cubed_sphere {
// Independent diagnostic of an overdetermined, geometry-only derivative fit.
// The actual nodal trace is retained. All degree1..degree coefficients are free;
// no field is overwritten/projected and no physical source is subtracted.
class AnchoredRadialScriProbe : public RadialScriJetProbe {
 public:
 int degree;
 static Row FitWeights(std::vector<Node> nodes,Real R,Basis basis,int degree){
  const int m=int(nodes.size())-1,d=degree;if(d<2||d>8||m<d||m>32)throw std::invalid_argument("anchored radial exact count/degree guard");Row out;out.nodes=std::move(nodes);out.first.resize(m+1);out.second.resize(m+1);std::vector<long double> z(m);long double scale=0;for(int i=0;i<m;++i){if(!(out.nodes[i].r>0&&out.nodes[i].r<R))throw std::runtime_error("anchored radial physical radius guard");z[i]=Coordinate(out.nodes[i].r,R,basis);scale=std::max(scale,std::abs(z[i]));}if(!(scale>0))throw std::runtime_error("anchored radial span guard");for(auto &v:z)v/=scale;
  std::vector<std::vector<long double>> Q(d,std::vector<long double>(m)),r(d,std::vector<long double>(d));for(int j=0;j<d;++j){std::vector<long double> v(m);for(int i=0;i<m;++i)v[i]=std::pow(z[i],j+1);for(int repeat=0;repeat<2;++repeat)for(int k=0;k<j;++k){long double dot=0;for(int i=0;i<m;++i)dot+=Q[k][i]*v[i];r[k][j]+=dot;for(int i=0;i<m;++i)v[i]-=dot*Q[k][i];}long double norm=0;for(auto a:v)norm+=a*a;norm=std::sqrt(norm);if(!(norm>1e-13L))throw std::runtime_error("anchored radial rank guard");r[j][j]=norm;for(int i=0;i<m;++i)Q[j][i]=v[i]/norm;}
  long double norm=0,invnorm=0;std::vector<std::vector<long double>> inv(d,std::vector<long double>(d));for(int col=0;col<d;++col)for(int i=d-1;i>=0;--i){long double v=i==col?1:0;for(int k=i+1;k<d;++k)v-=r[i][k]*inv[k][col];inv[i][col]=v/r[i][i];}for(int i=0;i<d;++i){long double s=0,t=0;for(int j=0;j<d;++j){s+=std::abs(r[i][j]);t+=std::abs(inv[i][j]);}norm=std::max(norm,s);invnorm=std::max(invnorm,t);}out.condition=norm*invnorm;if(!(out.condition<1e8))throw std::runtime_error("anchored radial condition guard");
  long double a=1,b=0;if(basis==Basis::Omega){a=-1;b=-1/(long double)R;}if(basis==Basis::LogRadius){a=-1/(long double)R;b=1/((long double)R*R);}std::vector<long double>w1(m),w2(m);for(int i=0;i<m;++i){for(int j=0;j<d;++j){w1[i]+=inv[0][j]*Q[j][i];w2[i]+=2*inv[1][j]*Q[j][i];}out.first[i]=a/scale*w1[i];out.second[i]=a*a/(scale*scale)*w2[i]+b/scale*w1[i];out.first[m]-=out.first[i];out.second[m]-=out.second[i];}
  for(int i=0;i<m;++i){w1[i]=(long double)out.first[i]*scale/a;w2[i]=(long double)out.second[i]*scale*scale/(a*a)-b*scale/(a*a)*w1[i];}
  for(int k=1;k<=d;++k){long double first=0,second=0;for(int i=0;i<m;++i){first+=w1[i]*std::pow(z[i],k);second+=w2[i]*std::pow(z[i],k);}out.reproduction=std::max({out.reproduction,Real(std::abs(first-(k==1?1:0))),Real(std::abs(second-(k==2?2:0)))});}if(!(out.reproduction<1e-10))throw std::runtime_error("anchored radial reproduction guard");for(Real v:out.first)out.first_l1+=std::abs(v);for(Real v:out.second)out.second_l1+=std::abs(v);return out;
 }
 AnchoredRadialScriProbe(const ScriSurface&s,int count,Basis mode,int degree=6):RadialScriJetProbe(s,7,mode),degree(degree){const auto baseline=rows;rows.clear();requested=count;condition=reproduction=first_ratio=second_ratio=0;const auto &g=s.grid;const Real R=g.mesh.radii.back();for(size_t p=0;p<s.rows.size();++p){const auto &row=s.rows[p];const auto &outer=g.mesh.blocks[row.block];std::vector<Node> candidates;for(size_t m=0;m<g.mesh.blocks.size();++m){const auto &block=g.mesh.blocks[m];if(block.face!=outer.face)continue;bool aligned=true;for(int a=1;a<3;++a)aligned=aligned&&std::abs(block.lo[a]-outer.lo[a])<1e-14&&std::abs(block.hi[a]-outer.hi[a])<1e-14;if(!aligned)continue;for(int i=0;i<g.n;++i){Real q[3]={(i+.5)/g.n,(row.j+.5)/g.n,(row.k+.5)/g.n},x[3];g.mesh.Forward(m,q,x);Real r=0;for(Real v:x)r+=v*v;r=std::sqrt(r);Real err=0;for(int a=0;a<3;++a)err=std::max(err,std::abs(x[a]/r-row.geometry.x[a]/R));if(err>1e-12)throw std::runtime_error("anchored radial nonaligned ray");candidates.push_back({r,g.Index(m,i,row.j,row.k)});}}
  std::sort(candidates.begin(),candidates.end(),[](const Node&a,const Node&b){return a.r>b.r;});if(count<degree+1||count>33||candidates.size()<size_t(count-1))throw std::runtime_error("anchored radial insufficient exact active nodes; no fallback");std::vector<Node> selected(candidates.begin(),candidates.begin()+count-1);std::reverse(selected.begin(),selected.end());selected.push_back({R,-1});auto fit=FitWeights(selected,R,mode,degree); // Amplification relative to SAME physical-r baseline, not log baseline.
  const auto rbase=Weights(baseline[p].nodes,R,Basis::Radius);fit.first_ratio=fit.first_l1/rbase.first_l1;fit.second_ratio=fit.second_l1/rbase.second_l1;if(!(fit.first_ratio<=4&&fit.second_ratio<=4))throw std::runtime_error("anchored radial amplification guard");condition=std::max(condition,fit.condition);reproduction=std::max(reproduction,fit.reproduction);first_ratio=std::max(first_ratio,fit.first_ratio);second_ratio=std::max(second_ratio,fit.second_ratio);rows.push_back(std::move(fit));}}
};
}
#endif
